// Smoke: every role can log in and sees the app. Read-only, safe on any environment.
// Generated by ownership-setup; the smoke-spec skill adds one core flow per role.
import { test, expect, loginPage } from '../../../../lib/qa.mjs';

test.describe('acme-leave smoke', () => {
  test('manager can log in', async ({ page, appName }) => {
    await loginPage(page, appName, 'manager');
    await expect(page.locator("[data-testid=who]")).toContainText(/\S/);
  });

  test('employee can log in', async ({ page, appName }) => {
    await loginPage(page, appName, 'employee');
    await expect(page.locator("[data-testid=who]")).toContainText(/\S/);
  });

  test('employee2 can log in', async ({ page, appName }) => {
    await loginPage(page, appName, 'employee2');
    await expect(page.locator("[data-testid=who]")).toContainText(/\S/);
  });
});
